// Aggregate-only structural diagnosis. No key/history bytes printed.
use pstfree::{ltp::{read_tc,Value,read_node_pc},ndb::Pst};use std::collections::BTreeMap;
fn main(){let mut p=Pst::open(&std::env::args().nth(1).unwrap()).unwrap();let ns=p.nodes();let mut counts=BTreeMap::new();let mut bynid:BTreeMap<u32,(Vec<u8>,Vec<u8>)>=BTreeMap::new();for t in ns.iter().filter(|n|matches!(n.nid_type(),14|15|16)){for r in read_tc(&mut p,t.bid_data,t.bid_sub).unwrap().rows{let Some(n)=ns.iter().find(|n|n.nid==r.id&&matches!(n.nid_type(),4|8))else{continue};let (Some(Value::Bytes(key)),Some(Value::Bytes(pcl)))=(r.props.get(&0x65e2),r.props.get(&0x65e3))else{continue};let pc=read_node_pc(&mut p,n).unwrap();let mut off=0;let mut valid=true;let mut contains=false;let mut entries=0;while off<pcl.len(){let len=pcl[off] as usize;off+=1;if !(17..=24).contains(&len)||off+len>pcl.len(){valid=false;break};contains|=&pcl[off..off+len]==key;off+=len;entries+=1;}let shape=format!("key_length={} key_valid_length={} pcl_length={} pcl_valid={} pcl_entries={} contains_key={} both_absent_pc={}",key.len(),(17..=24).contains(&key.len()),pcl.len(),valid,entries,contains,!pc.props.contains_key(&0x65e2)&&!pc.props.contains_key(&0x65e3));*counts.entry(shape).or_insert(0)+=1;if let Some(old)=bynid.insert(r.id,(key.clone(),pcl.clone())){assert_eq!(old,(key.clone(),pcl.clone()))}}}println!("distinct_items={} shape_counts={:?}",bynid.len(),counts)}
